// Writes src/data/tables/index.ts: static imports of every stored PSI run table, so the
// server code (and the bundled Vercel functions) never read table files from disk.
// Run automatically by sync:tables and data:normalize.
import { readFileSync, writeFileSync } from "node:fs";

const manifest = JSON.parse(readFileSync("src/data/table-manifest.json", "utf8"));
const ids = manifest.tables.map((t) => t.id).sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));
const name = (id) => "t_" + id.replace(/-/g, "_");
const src = [
  "// Generated by scripts/index-tables.mjs. Do not edit.",
  "export interface RunTable { header: string[]; rows: { sourceRow: number; cells: string[] }[] }",
  ...ids.map((id) => `import ${name(id)} from "./${id}.json";`),
  "export const TABLES: Record<string, RunTable> = {",
  ...ids.map((id) => `  "${id}": ${name(id)} as RunTable,`),
  "};",
  "",
].join("\n");
writeFileSync("src/data/tables/index.ts", src);
console.log(`Indexed ${ids.length} run tables in src/data/tables/index.ts`);
